const body = $json.body ?? {};
const history = Array.isArray(body.history) ? body.history : [];
const userMessage = (body.message ?? '').toString().trim();
const conversationId = (body.conversation_id ?? `conv_${Date.now()}`).toString();

const systemPrompt = `You are Yusr Assistant for an Islamic app.
- Understand colloquial Arabic.
- Return JSON only.
- Never execute actions yourself.
- Types: answer, ask_for_missing_info, action_proposal, action_ready.
- For reminder actions ensure title,type,hour,minute,repeat are complete.
- If missing data ask clearly in Arabic.
- If complete but not confirmed return action_proposal.
- If user confirmed (yes/نعم/أكيد/نفذ) return action_ready.`;

const historyText = history
  .filter((item) => item && item.text)
  .map((item) => `${item.role === 'assistant' ? 'assistant' : 'user'}: ${item.text.toString()}`)
  .join('\n');

const llmPrompt = [
  systemPrompt,
  historyText ? `Conversation history:\n${historyText}` : '',
  `Current user message:\n${userMessage}`,
  'Return valid JSON only.'
].filter(Boolean).join('\n\n');

return [{
  json: {
    user_id: (body.user_id ?? '').toString(),
    locale: (body.locale ?? 'ar').toString(),
    timezone: (body.timezone ?? 'Asia/Riyadh').toString(),
    user_message: userMessage,
    conversation_id: conversationId,
    llm_prompt: llmPrompt,
  },
}];

const source = $items('Prepare Input', 0, 0)[0].json;

const fallback = {
  type: 'answer',
  reply_text: 'حدث خطأ في تحليل رد المساعد. حاول مرة أخرى.',
  intent: 'general_question',
};

const stripCodeFence = (text) => {
  const trimmed = String(text ?? '').trim();
  if (!trimmed.startsWith('```')) return trimmed;
  const withoutStart = trimmed.replace(/^```[a-zA-Z0-9_-]*\s*/, '');
  return withoutStart.replace(/\s*```$/, '').trim();
};

const tryParse = (value) => {
  const text = String(value ?? '').trim();
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch (_) {}

  const stripped = stripCodeFence(text);
  if (stripped !== text) {
    try {
      return JSON.parse(stripped);
    } catch (_) {}
  }

  return null;
};

const raw = $json?.text ?? $json?.response?.text ?? $json;
let parsed = null;

if (typeof raw === 'string') {
  parsed = tryParse(raw) ?? fallback;
} else if (Array.isArray(raw) && raw.length > 0) {
  const first = raw[0];
  parsed = (first && typeof first === 'object') ? first : (tryParse(first) ?? fallback);
} else if (raw && typeof raw === 'object') {
  parsed = raw;
} else {
  parsed = fallback;
}

if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
  if (parsed.type == null && typeof parsed.text === 'string') {
    const nested = tryParse(parsed.text);
    if (nested && typeof nested === 'object' && !Array.isArray(nested)) {
      parsed = nested;
    }
  }

  if (parsed.reply_text == null && typeof parsed.message === 'string') {
    parsed = { ...parsed, reply_text: parsed.message };
  }
}

const allowedTypes = new Set(['answer', 'ask_for_missing_info', 'action_proposal', 'action_ready']);
if (!allowedTypes.has(parsed?.type)) {
  parsed = { ...parsed, type: 'answer' };
}

return [{
  json: {
    ...parsed,
    conversation_id: parsed.conversation_id ?? source.conversation_id,
    user_id: source.user_id,
    user_message: source.user_message,
  },
}];

const source = $items('Switch Action Name', 0, 0)[0].json;

if ($json.error) {
  return [{
    json: {
      ...source,
      type: 'action_ready',
      executed: false,
      reply_text: 'تعذر تنفيذ إضافة التذكير على قاعدة البيانات.',
      db_error: $json.error,
    },
  }];
}

return [{
  json: {
    ...source,
    type: 'action_ready',
    executed: true,
    reply_text: source.reply_text ?? 'تمت إضافة التذكير بنجاح.',
    db_result: $json,
  },
}];

const source = $items('Switch Action Name', 1, 0)[0].json;

if (!source.action?.data?.id) {
  return [{
    json: {
      ...source,
      type: 'action_ready',
      executed: false,
      reply_text: 'فشل التنفيذ: reminder id غير موجود للتعديل.',
    },
  }];
}

if ($json.error) {
  return [{
    json: {
      ...source,
      type: 'action_ready',
      executed: false,
      reply_text: 'تعذر تنفيذ تعديل التذكير على قاعدة البيانات.',
      db_error: $json.error,
    },
  }];
}

return [{
  json: {
    ...source,
    type: 'action_ready',
    executed: true,
    reply_text: source.reply_text ?? 'تم تعديل التذكير بنجاح.',
    db_result: $json,
  },
}];

const source = $items('Switch Action Name', 2, 0)[0].json;

if (!source.action?.data?.id) {
  return [{
    json: {
      ...source,
      type: 'action_ready',
      executed: false,
      reply_text: 'فشل التنفيذ: reminder id غير موجود للحذف.',
    },
  }];
}

if ($json.error) {
  return [{
    json: {
      ...source,
      type: 'action_ready',
      executed: false,
      reply_text: 'تعذر تنفيذ حذف التذكير على قاعدة البيانات.',
      db_error: $json.error,
    },
  }];
}

return [{
  json: {
    ...source,
    type: 'action_ready',
    executed: true,
    reply_text: source.reply_text ?? 'تم حذف التذكير بنجاح.',
    db_result: $json,
  },
}];

return [{
  json: {
    ...$json,
    type: 'action_ready',
    executed: false,
    reply_text: 'الإجراء المطلوب غير مدعوم حاليًا.',
  },
}];
